using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class MarinaPropWrappingFix{static MarinaPropWrappingFix(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("MarinaPropWrappingFix.request"))return;File.Delete("MarinaPropWrappingFix.request");foreach(string name in new[]{"Existing Garden Lamp","Existing Striped Road Bollard","Existing Traffic Cone","Existing Yellow Barrier"}){var mesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scenes/Oasis/YachtPortAtlas/Meshes/"+name+" Original Prop.asset");var uv=new List<Vector4>();mesh.GetUVs(1,uv);for(int i=0;i<uv.Count;i++)uv[i]=new Vector4(8,0,0,0);mesh.SetUVs(1,uv);EditorUtility.SetDirty(mesh);}var imp=(TextureImporter)AssetImporter.GetAtPath("Assets/Scenes/Oasis/3D/Texture/Roads Props/Roads-Props.jpg");imp.isReadable=false;imp.SaveAndReimport();AssetDatabase.SaveAssets();File.AppendAllText("FinalEnvironmentRoadReview/MarinaExistingPropsFinal.txt","\nNative prop UV repeat restored; exact native atlas coordinates preserved; original props texture CPU-readability disabled after packing.");}}
